public protocol IslandStateListener : AnyObject {
    
    func onStateChanged(newState: FfiIslandViewState) 
    
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceIslandStateListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    static var vtable: UniffiVTableCallbackInterfaceIslandStateListener = UniffiVTableCallbackInterfaceIslandStateListener(
        onStateChanged: { (
            uniffiHandle: UInt64,
            newState: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceIslandStateListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onStateChanged(
                     newState: try FfiConverterTypeFfiIslandViewState.lift(newState)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterCallbackInterfaceIslandStateListener.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface IslandStateListener: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitIslandStateListener() {
    uniffi_island_bridge_fn_init_callback_vtable_islandstatelistener(&UniffiCallbackInterfaceIslandStateListener.vtable)
}

